('48f8b37c-881f-4f0d-a945-2659ebfe3f37', 'Kesesuaian Sistem dengan Perdirut Mengenai Juknis Penilaian Aktivitas Medik, Pengenaan Tarif dan Pembagian Jasa Medik', 'Sistem yang saat ini berjalan di HISFS masih memerlukan evaluasi karena belum mengimplementasikan yang tertulis dalam Perdirut. hal ini bisa menyebabkan kebingungan di layanan di karenakan Perdirut yang sudah diseminasikan tidak sesuai dengan yang ada di lapangan.', 'HTO', 'cc198c39-16ca-4432-9f7c-b6a1fedaeeec', 'Aura Narita', 'approved', 'medium', NULL, 'planning', '{"evaluation":"","execution":"","followup":"","planning":""}', false, '2026-02-02', '2026-03-06', '2026-02-11 02:04:11.559697+00', '2026-04-13 08:01:30.710171+00', 'medium', 'a5e5d868-32bd-40aa-b911-556b9d268749', 'medium', 'https://ycbpxbqbzbyhuqqrnczp.supabase.co/storage/v1/object/public/project-attachments/cc198c39-16ca-4432-9f7c-b6a1fedaeeec/1770775448212.pdf', 'completed', NULL, '30', 'fqoi2rnpnrk7armqt6ilqrmeh0', NULL, NULL, false),
('0cb04e8c-53cb-4911-9f82-d68e94a03572', 'Platform Komunikasi Internal', 'Dalam organisasi yang memiliki banyak direktorat dan unit kerja, komunikasi internal memegang peranan penting dalam memastikan kebijakan, arahan manajemen, serta informasi strategis dapat dipahami dan dijalankan secara selaras. 

Dalam pelaksanaannya, penyampaian informasi sering kali tersebar di berbagai media dan kanal yang berbeda, sehingga menimbulkan informasi yang tidak terpusat, duplikasi penyampaian, serta potensi miskomunikasi antar unit kerja.

Sebagai bentuk penguatan ekosistem komunikasi internal, platform ini terintegrasi dengan sistem Helpdesk melalui fitur “Ajukan Pertanyaan / Tindak Lanjut”, sehingga pengguna tidak hanya menerima informasi secara satu arah, tetapi juga dapat melakukan klarifikasi, konsultasi, atau tindak lanjut secara resmi dan terdokumentasi. Dengan demikian, Platform Komunikasi Internal tidak hanya berfungsi sebagai media informasi, tetapi juga sebagai alat strategis untuk meningkatkan koordinasi, kepatuhan kebijakan, dan efektivitas tata kelola organisasi.', 'HTO', 'ae199846-f8f2-4f4b-998d-ea5f88b6a520', 'Rizq Alhaz thoriq', 'rejected', 'medium', 'Effort terlalu tinggi untuk impact yang rendah', 'planning', '{"evaluation":"","execution":"","followup":"","planning":""}', false, '2026-02-10', '2026-05-31', '2026-02-10 02:58:30.657794+00', '2026-04-13 08:12:17.968411+00', 'medium', 'd8e3c3c6-3cb7-49ba-96ab-bb7738b1a49a', 'medium', NULL, 'in_progress', NULL, '30', NULL, NULL, NULL, false),
