('47b80538-4a09-4399-a492-57513cef8d91', 'Remunerasi Radiologi Anak', 'Dokter radiologi anak belum mendapatkan jasa medis dari Januari 2025 hingga Maret 2026. Hal ini disebabkan karena perbedaan sistem pada radiologi pusat dan radiologi anak, di mana radiologi pusat menggunakan CPOE dan menjawab expertise melalui PACS yang terintegrasi dengan HIS. Sedangkan, radiologi anak di order melalui CPOE tetapi menjawab melalui laporan tindakan, sehingga aktivitasnya tidak dibayarkan jasa medisnya karena jasa medis diverifikasi melalui jawaban dari PACS.', 'HTO', '8ae26dd7-a8e2-4251-8271-458b129f45b2', 'Rashida Aqila Khairunnisa', 'approved', 'low', NULL, 'planning', '{"evaluation":"","execution":"","followup":"","planning":""}', false, '2026-04-13', '2026-04-13', '2026-04-13 08:39:50.654492+00', '2026-06-23 09:07:26.412694+00', 'medium', '1e1ec17d-6a55-4dd4-a4df-50b16a604568', 'medium', NULL, 'on_hold', 'Akan diselesaikan oleh direksi dan komite medik', '30', 'mvqo8g1eud25t2u1g4vvv11sbo', NULL, NULL, false)
